@define-color shade_color rgba(0, 0, 6, 0.07);
@define-color scrollbar_outline_color white;

/*
 * Structural fallback for non-libadwaita GTK4 apps.
 * libadwaita apps recolor from the named colors above, but plain GTK4
 * apps need the window surface painted explicitly or it renders
 * transparent.
 */
window,
.background {
  background-color: @window_bg_color;
  color: @window_fg_color;
}
